            "x": 80,
            "y": 670,
            "width": 280,
            "height": 460,
            "text": "Global container dwell times increased by 38% across major transpacific maritime junctions in the preceding fiscal cycle. Legacy just-in-time procurement systems proved systematically incapable of buffering cascading delays.\n\nOur field examination of 450 industrial enterprise nodes across 28 global maritime hubs reveals a clear structural bifurcation: firms maintaining decentralized buffer inventories and automated multi-carrier rerouting reduced disruption costs by 62%.",
