            "text": "1. Mandate dynamic dual-sourcing for any bill-of-materials SKU representing >8% of gross margin exposure.\n2. Contract for guaranteed intermodal rail capacity at on-dock port terminals 18 months in advance.\n3. Integrate live satellite transponder AIS telemetry directly into ERP replenishment triggers.",
