            "y": 1015,
            "width": 320,
            "height": 300,
            "text": "Manufacturing economies of scale have compressed PEM stack capital expenditures by 32% since 2023. Gigawatt-scale automated gigafactories in Germany and Spain are lowering unit production costs toward parity with fossil fuels.",
