            "y": 930,
            "width": 490,
            "height": 160,
            "text": "“To witness the irreversible return of ice locked before the dawn of human agriculture is both a privilege of inquiry and a sobering testament to planetary transformation.”",
            "fontSize": 20,
            "fontFamily": "Cormorant Garamond",
            "fontStyle": "italic",
            "fill": "#d97706",
