            "y": 1120,
            "width": 490,
            "height": 320,
            "text": "Methane seep bubbles break the surface of thermokarst melt lakes continuously throughout the polar summer, whispering ancient gases back into the modern stratosphere in an accelerating positive feedback loop.\n\nField observations by Dr. Henrik Lindqvist, Senior Paleoclimatologist.",
            "fontSize": 15,
